// book_where returns the conditions of a `BookWhereInput`.
fn book_where(w map[string]graphql.Value) ![]load.Cond {
	mut conds := []load.Cond{}
	for key, v in w {
		if v is graphql.Null {
			continue
		}
		match key {
			'not' {
				conds << load.not(load.and(...book_where(v.as_map())!))
			}
			'and' {
				for item in v.as_list() {
					conds << book_where(item.as_map())!
				}
			}
			'or' {
				mut any := []load.Cond{}
				for item in v.as_list() {
					any << load.and(...book_where(item.as_map())!)
				}
				conds << load.or(...any)
			}
			'id' { conds << load.eq('id', gql_int_id(v)!) }
			'idNEQ' { conds << load.ne('id', gql_int_id(v)!) }
			'idIn' { conds << load.in_ints('id', gql_int_ids(v)!) }
			'idNotIn' { conds << load.not_in_ints('id', gql_int_ids(v)!) }
			'idGT' { conds << load.gt('id', gql_int_id(v)!) }
			'idGTE' { conds << load.ge('id', gql_int_id(v)!) }
			'idLT' { conds << load.lt('id', gql_int_id(v)!) }
			'idLTE' { conds << load.le('id', gql_int_id(v)!) }
			'title' { conds << load.eq('title', v.as_string()) }
			'titleNEQ' { conds << load.ne('title', v.as_string()) }
			'titleIn' { conds << load.in_strings('title', gql_strings(v)) }
			'titleNotIn' { conds << load.not_in_strings('title', gql_strings(v)) }
			'titleGT' { conds << load.gt('title', v.as_string()) }
			'titleGTE' { conds << load.ge('title', v.as_string()) }
			'titleLT' { conds << load.lt('title', v.as_string()) }
			'titleLTE' { conds << load.le('title', v.as_string()) }
			'titleContains' { conds << load.contains('title', v.as_string()) }
			'titleHasPrefix' { conds << load.has_prefix('title', v.as_string()) }
			'titleHasSuffix' { conds << load.has_suffix('title', v.as_string()) }
			'titleEqualFold' { conds << load.equal_fold('title', v.as_string()) }
			'titleContainsFold' { conds << load.contains_fold('title', v.as_string()) }
			'year' { conds << load.eq('year', v.as_int()) }
			'yearNEQ' { conds << load.ne('year', v.as_int()) }
			'yearIn' { conds << load.in_ints('year', gql_ints(v)) }
			'yearNotIn' { conds << load.not_in_ints('year', gql_ints(v)) }
			'yearGT' { conds << load.gt('year', v.as_int()) }
			'yearGTE' { conds << load.ge('year', v.as_int()) }
			'yearLT' { conds << load.lt('year', v.as_int()) }
			'yearLTE' { conds << load.le('year', v.as_int()) }
			'pages' { conds << load.eq('pages', v.as_int()) }
			'pagesNEQ' { conds << load.ne('pages', v.as_int()) }
			'pagesIn' { conds << load.in_ints('pages', gql_ints(v)) }
			'pagesNotIn' { conds << load.not_in_ints('pages', gql_ints(v)) }
			'pagesGT' { conds << load.gt('pages', v.as_int()) }
			'pagesGTE' { conds << load.ge('pages', v.as_int()) }
			'pagesLT' { conds << load.lt('pages', v.as_int()) }
			'pagesLTE' { conds << load.le('pages', v.as_int()) }
			'hasAuthors' {
				conds << if v.as_bool() { book_has_authors() } else { load.not(book_has_authors()) }
			}
			'hasAuthorsWith' {
				mut all := []load.Cond{}
				for item in v.as_list() {
					all << author_where(item.as_map())!
				}
				conds << book_has_authors_with(...all)
			}
			else {}
		}
	}
	return conds
}

// book_connection returns the page of `q` that a `BookConnection`'s arguments
// ask for, bounded by `size`, and how many rows `q` matches when `totalCount`
// is asked for.
fn book_connection(q BookQuery, info graphql.FieldInfo, size graphql.PageSize) !graphql.Connection {
	p := graphql.page_args(info.args, size)!
	orders := book_order(info.arg('orderBy'), true)!
	rows := q.graphql_paged(orders, p)!.all()!
	total := if info.selected('totalCount') { q.count()! } else { 0 }
	return book_page(q.graph, rows, orders, p, total)
}

// graphql_paged returns `q` in `orders`, which end with the key (reversed for
// `last`), past the cursors of `p`, and limited to one row past the page.
fn (q BookQuery) graphql_paged(orders []load.Order, p graphql.PageArgs) !BookQuery {
	types := orders.map(it.typ)
	nulls := load.nulls_largest(q.graph.client.conn)
	mut conds := q.query.conds.clone()
	if c := p.after {
		conds << load.keyset(orders, load.decode_cursor(c, types)!, true, nulls)!
	}
	if c := p.before {
		conds << load.keyset(orders, load.decode_cursor(c, types)!, false, nulls)!
	}
	backward := p.last != none
	mut next := q
	next.query = load.Query{
		...q.query
		conds:  conds
		order:  ''
		desc:   false
		orders: if backward { orders.map(load.Order{ ...it, desc: !it.desc }) } else { orders }
		limit:  if c := p.first {
			c + 1
		} else if c := p.last {
			c + 1
		} else {
			0
		}
		offset: 0
	}
	return next
}

// book_page returns `nodes`, read in `orders` (reversed for `last`) and one row
// past the page, as a connection.
fn book_page(g Graph, nodes []BookNode, orders []load.Order, p graphql.PageArgs, total int) !graphql.Connection {
	mut page := nodes.clone()
	mut has_next := false
	mut has_previous := false
	if count := p.first {
		if page.len > count {
			has_next = true
			page = page[..count].clone()
		}
	} else if count := p.last {
		if page.len > count {
			has_previous = true
			page = page[..count].clone()
		}
		page.reverse_in_place()
	}
	cursors := book_cursors(g, page.map(it.book), orders)!
	return graphql.connection(page.map(graphql.Source(it)), cursors, has_next, has_previous, total)
}

// book_cursors returns the cursors of `rows`: the values of their order
// columns, those of edges read in one query.
fn book_cursors(g Graph, rows []models.Book, orders []load.Order) ![]string {
	exprs := load.expr_values(g.client.conn, 'books', 'id', .int,
		rows.map(it.id.str()), orders)!
	mut out := []string{cap: rows.len}
	for row in rows {
		from_exprs := exprs[row.id.str()] or { []orm.Primitive{} }
		mut values := []orm.Primitive{cap: orders.len}
		for i, o in orders {
			values << if o.expr != '' {
				from_exprs[i] or { orm.Primitive(orm.Null{}) }
			} else {
				book_order_value(row, o.column)
			}
		}
		out << load.encode_cursor(values)
	}
	return out
}

// book_order_value returns a column of a `books` row, for a cursor.
fn book_order_value(row models.Book, column string) orm.Primitive {
	return match column {
		'id' { orm.Primitive(row.id) }
		'title' { orm.Primitive(row.title) }
		'year' { orm.Primitive(row.year) }
		'pages' { orm.Primitive(row.pages) }
		else { orm.Primitive(orm.Null{}) }
	}
}

// book_create_input reads the input of `createBook`.
fn book_create_input(value graphql.Value) !CreateBookInput {
	mut input := CreateBookInput{}
	for name, v in value.as_map() {
		if v is graphql.Null {
			continue
		}
		match name {
			'title' {
				input.title = v.as_string()
			}
			'year' {
				input.year = v.as_int()
			}
			'pages' {
				input.pages = v.as_int()
			}
			'authorIDs' {
				input.author_ids = gql_int_ids(v)!
			}
			else {}
		}
	}
	return input
}

// book_update_input reads the input of `updateBook`.
fn book_update_input(value graphql.Value) !UpdateBookInput {
	mut input := UpdateBookInput{}
	for name, v in value.as_map() {
		if v is graphql.Null {
			continue
		}
		match name {
			'title' {
				input.title = v.as_string()
			}
			'year' {
				input.year = v.as_int()
			}
			'pages' {
				input.pages = v.as_int()
			}
			'addAuthorIDs' {
				input.add_author_ids = gql_int_ids(v)!
			}
			'removeAuthorIDs' {
				input.remove_author_ids = gql_int_ids(v)!
			}
			'clearAuthors' {
				input.clear_authors = v.as_bool()
			}
			else {}
		}
	}
	return input
}

// gql_int_id reads an int key from an ID.
fn gql_int_id(v graphql.Value) !int {
	s := v.as_string()
	n := s.int()
	if n.str() != s {
		return error('invalid ID "${s}"')
	}
	return n
}

fn gql_int_ids(v graphql.Value) ![]int {
	mut out := []int{}
	for item in v.as_list() {
		out << gql_int_id(item)!
	}
	return out
}

fn gql_ints(v graphql.Value) []int {
	return v.as_list().map(it.as_int())
}

fn gql_strings(v graphql.Value) []string {
	return v.as_list().map(it.as_string())
}
